import { z } from 'zod';
import { TrnscTypeCd } from '~/shared/api/dtos/enums';

export const BaseExchangeContextSchema = z
  .object({
    tokenId: z.string().optional(),
    trnscTypeCd: z.nativeEnum(TrnscTypeCd).optional(),
    trnscAmt: z.string().optional(),
    trnscId: z.string().optional(),
    txCd: z.string().optional(), //260323 추가

    reqAliasNm: z.string().optional(), //260417 추가 (선택한 지갑)

    // 오류 정보
    error: z.any().optional(),

    // 완료 결과
    result: z.any().optional(),

    redirectPath: z.string().optional().nullable(),
  })
  .partial(); // 모든 필드를 optional로 만듦

export type BaseExchangeContext = z.infer<typeof BaseExchangeContextSchema>;
